<?php ob_start(); ?><h1>Operation reports</h1><form method="get"><input name="q" value="<?= esc($q) ?>" placeholder="S/O, machine, supervisor"><input name="date" type="date" value="<?= esc($date ?? '') ?>"><button>Search</button><a href="<?= site_url('admin/operations') ?>">Clear</a></form><section><table><thead><tr><th>S/O</th><th>Machine</th><th>Sector / activity</th><th>Supervisor</th><th>Status</th><th>Start / end</th><th>Passed / rejected</th><th></th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= esc($row['so_number'] ?? '—') ?></td><td><?= esc($row['machine_name']) ?></td><td><?= esc($row['sector_name'].' / '.$row['activity_name']) ?></td><td><?= esc($row['supervisor_name']) ?></td><td><?= esc($row['status']) ?></td><td><?= esc($row['started_at'] ?? '—') ?><br><?= esc($row['ended_at'] ?? '—') ?></td><td><?= esc($row['qty_passed'] ?? '—') ?> / <?= esc($row['qty_rejected'] ?? '—') ?></td><td><a href="<?= site_url('admin/operations/'.$row['id']) ?>">Open</a></td></tr><?php endforeach ?></tbody></table><?= $pager->links() ?></section><?php $content=ob_get_clean(); echo view('admin/shell',['title'=>$title,'content'=>$content]); ?>
